const jwt = "JWT eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJ1c2VyX2lkIjo4ODQ2MywidXNlcm5hbWUiOjg4NDYzLCJleHAiOjE3NzYzMTc4NDYsImVtYWlsIjoidXRwYWwyMzVAeWFob28uY29tIiwiaWQiOjg4NDYzLCJpbnN0aXR1dGUiOjE1MDl9.xcrfRS1jZA3H44ixYV0t_5HWgna7T0e5-lJG61ZtM8M";

const courseIds = [1112 ,1161, 1242, 1245, 1255, 1295, 1296, 1303, 1304, 1305];

// ---- Build chapter_id -> title map. No positional [0]/[1] assumption. ----
const chapterTitleById = {};
const verbalLectureDates = {};
for (const course_id of courseIds) {
  let url = `https://catking.testpress.in/api/v2.5/admin/courses/${course_id}/chapters/?limit=100`;
  while (url) {
