  if (
      chapterName.includes('verbal kickstarter')
  ) {

      let contentUrl =
        `https://catking.testpress.in/api/v2.4/courses/${course_id}/contents/?include_child_contents=true`;

      const contents = await helpers.request({
          method: 'GET',
          url: contentUrl,
