      for (const lecture of (contents.results?.contents || [])) {

          if (
              lecture.chapter_id == c.id &&
              lecture.start
          ) {

              verbalLectureDates[course_id].push(
                  lecture.start.slice(0,10)
              );

          }

      }

  }

}
 url = r.next || null;
}
}
const VPAR_TITLE_RE = /starter\s*module\s*vpar|vpar/i;
const isVparSession = (chapter_id) =>
  VPAR_TITLE_RE.test(chapterTitleById[String(chapter_id)] || '');

const MONTHS = { jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12' };
function toISODate(s) {
  if (!s) return '';
  s = String(s).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  m = s.match(/^(\d{1,2})[\-\s]([A-Za-z]{3,})[\-\s](\d{4})$/);
  if (m && MONTHS[m[2].slice(0,3).toLowerCase()]) {
    return `${m[3]}-${MONTHS[m[2].slice(0,3).toLowerCase()]}-${m[1].padStart(2,'0')}`;
  }
  const d = new Date(s);
  return isNaN(d) ? '' : d.toISOString().slice(0, 10);
}

function hasVerbalWeek(studentStartDate, courseId){

    if(!studentStartDate) return false;

    const lectures = verbalLectureDates[String(courseId)] || [];

    const start = new Date(studentStartDate);

    const end = new Date(studentStartDate);
    end.setDate(end.getDate() + 6);

    for(const d of lectures){

        const lectureDate = new Date(d);

        if(lectureDate >= start && lectureDate <= end){
            return true;
        }

    }

    return false;

}

const allAttended = $('FORMATTING NODE: Compares the google sheet data with JSON Data').all().map(i => i.json);

const rawSheetRows = $('Order Export (Batch Strength, Last 1.5 years)').all().map(i => i.json);

// Dedupe true duplicate rows: same student + same set of course IDs (order-independent).
// Different course ID sets for the same email = legitimate separate purchase, kept as-is.
const seenRowKeys = new Set();
const sheetRows = [];
for (const row of rawSheetRows) {
  const email = row['Email']?.toLowerCase().trim();
  if (!email) continue;

  const courseIdSet = String(row['TestPress Course Ids'] || '')
    .split('|')
    .map(c => c.trim())
    .filter(Boolean)
    .sort()
    .join('|');

  const key = `${email}|${courseIdSet}`;

  if (seenRowKeys.has(key)) continue;
  seenRowKeys.add(key);
  sheetRows.push(row);
}

const result = [];
const seen = new Set();

const batchMap = { '1112': 'A1', '1161': 'M1.1', '1245': 'M1.2', '1242': 'A2', '1255': 'A3', '1295': 'A4', '1296': 'M2.1', '1303': 'A5', '1305': 'M2.2'};

// ============================================================
// Date now comes from the "Manual Date (EDIT HERE)" node so the
// whole workflow (API fetch window + this filter) stays in sync.
// Leave that field blank for live/automatic mode (today's date).
// Put a date like "2026-06-30" there to pull absentees for any
// past date.
// ============================================================
const manualDate = $('Manual Date (EDIT HERE)').first().json.manual_date;

const targetDate = manualDate
    ? manualDate
    : new Date().toISOString().slice(0, 10);

// ---- FIRST LOOP: Count present/absent per content ----
const countsByContent = {};
for (const data of allAttended) {
  if (data.session_date !== targetDate) continue;

  const course_id = String(data.course_id);
  const contentId = String(data.chapter_content_id);
  const attendedEmails = data.attended_emails || [];
  const sessionDate = data.session_date;
  const vpar = isVparSession(data.chapter_id);

  let absent_count = 0;
  for (const student of sheetRows) {
    const studentEmail = student['Email']?.toLowerCase().trim();
    if (!studentEmail) continue;
    const rawCourses = student['TestPress Course Ids'];
    if (!rawCourses) continue;
    if (!String(rawCourses).split('|').map(c => c.trim()).includes(course_id)) continue;

    const studentStartDate = toISODate(student['TestPress Course Start Date']);
    if (studentStartDate && sessionDate < studentStartDate) continue;

    const dayDiff = studentStartDate
      ? Math.floor((new Date(sessionDate) - new Date(studentStartDate)) / 86400000)
      : 9999;

   if (vpar) continue;
    const reminderDelay =
    hasVerbalWeek(studentStartDate, course_id)
        ? 14
        : 7;


if (dayDiff >= 0 && dayDiff < reminderDelay)
    continue;

    if (!attendedEmails.includes(studentEmail)) absent_count++;
  }

  countsByContent[contentId] = { present_count: attendedEmails.length, absent_count };
}

// ---- SECOND LOOP: Build reminder list ----
for (const data of allAttended) {
  if (data.session_date !== targetDate) continue;

  const course_id = String(data.course_id);
  const attendedEmails = data.attended_emails || [];
  const lectureTitle = data.lecture_title;
  const contentId = String(data.chapter_content_id);
  const batch = batchMap[course_id] || course_id;
  const sessionDate = data.session_date;
  const vpar = isVparSession(data.chapter_id);

  for (const student of sheetRows) {
    const studentEmail = student['Email']?.toLowerCase().trim();
    if (!studentEmail) continue;
    const rawCourses = student['TestPress Course Ids'];
    if (!rawCourses) continue;
    if (!String(rawCourses).split('|').map(c => c.trim()).includes(course_id)) continue;

    const studentStartDate = toISODate(student['TestPress Course Start Date']);
    if (studentStartDate && sessionDate < studentStartDate) continue;

    const dayDiff = studentStartDate
      ? Math.floor((new Date(sessionDate) - new Date(studentStartDate)) / 86400000)
      : 9999;

    if (vpar) continue;
    const reminderDelay =
    hasVerbalWeek(studentStartDate, course_id)
        ? 14
        : 7;


if (dayDiff >= 0 && dayDiff < reminderDelay)
    continue;

    if (attendedEmails.includes(studentEmail)) continue;

    const uid = `${studentEmail}-${course_id}-${lectureTitle}-${sessionDate}`;
    if (seen.has(uid)) continue;
    seen.add(uid);

    result.push({
      json: {
        batch,
        lecture_title: lectureTitle,
        chapter_content_id: contentId,
        name: student['Billing Detail Name'],
        phone: String(student['Billing Detail Phone Number']),
        whatsapp: String(student['Billing Detail Whatsapp Number']),
        email: student['Email'],
        course_id,
        present_count: countsByContent[contentId]?.present_count ?? 0,
        absent_count: countsByContent[contentId]?.absent_count ?? 0,
        session_date: sessionDate
      }
    });
  }
}

return result;

const items = [];
const courseIds = [1112, 1161, 1245, 1242, 1255, 1295, 1296, 1303, 1304, 1305];

// ============================================================
// Pulls the date from the "Manual Date (EDIT HERE)" node.
// Leave that field blank to run for today (normal nightly mode).
// Put a date like "2026-06-30" there to test/re-run any past date.
// ============================================================
const manualDate = $('Manual Date (EDIT HERE)').first().json.manual_date;

const today = manualDate ? new Date(manualDate) : new Date();
const todayStr = manualDate || today.toISOString().slice(0, 10);

const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);
const afterStr = yesterday.toISOString().slice(0, 10);

const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);
const beforeStr = tomorrow.toISOString().slice(0, 10);

for (const course_id of courseIds) {
  items.push({
    json: {
      course_id,
      completed_after: afterStr,
      completed_before: beforeStr,
