    course = match[1].trim();
    time = match[2].trim();
  }

  const rawPhone = String(d.whatsapp || d.phone || '').replace(/\D/g, '');
  if (!rawPhone) continue;

  const fullPhone = rawPhone.startsWith('91') ? rawPhone : `91${rawPhone}`;
