// ============================================================
// DAILY ATTENDANCE SUMMARY
// Per batch -> per lecture: present, absent, % attendance.
// Absent = student enrolled in that course (per the sheet), whose
// course start date is on/before the session date, who did not attend.
// ============================================================

// ---- EDIT: course ID -> batch name ----
const batchMap = {
  '1112': 'A1', '1161': 'M1.1', '1245': 'M1.2', '1242': 'A2', '1255': 'A3',
  '1295': 'A4', '1296': 'M2.1', '1303': 'A5', '1304': 'B1', '1305': 'M2.2'
};

// ---- EDIT: ID of the attendance Google Sheet (the long part of its URL between /d/ and /edit) ----
const ATTENDANCE_SHEET_ID = '16eux3sw3qfUboiOZq0wvS7a-dpTbySgMylwBz60StoM';
const SHEET_URL = `https://docs.google.com/spreadsheets/d/${ATTENDANCE_SHEET_ID}/edit`;

const manualDate = $('Manual Date (EDIT HERE)').first().json.manual_date;
const targetDate = manualDate ? manualDate : new Date().toISOString().slice(0, 10);

const MONTHS = { jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12' };
function toISODate(s) {
  if (!s) return '';
  s = String(s).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  m = s.match(/^(\d{1,2})[\-\s]([A-Za-z]{3,})[\-\s](\d{4})$/);
  if (m && MONTHS[m[2].slice(0,3).toLowerCase()]) {
    return `${m[3]}-${MONTHS[m[2].slice(0,3).toLowerCase()]}-${m[1].padStart(2,'0')}`;
  }
  const d = new Date(s);
  return isNaN(d) ? '' : d.toISOString().slice(0, 10);
}

const prettyDateOf = d => new Date(d + 'T00:00:00Z')
  .toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ---- Enrolment per course from the sheet (one entry per email per course) ----
const sheetRows = $('Order Export (Batch Strength, Last 1.5 years)').all().map(i => i.json);
const enrolled = {}; // course_id -> Map(email -> earliest start date or '')
const studentInfo = {}; // email -> { name, phone }
for (const row of sheetRows) {
  const email = row['Email']?.toLowerCase().trim();
  if (!email) continue;
  if (!studentInfo[email]) {
    studentInfo[email] = {
      name: String(row['Billing Detail Name'] || '').trim(),
      phone: String(row['Billing Detail Whatsapp Number'] || row['Billing Detail Phone Number'] || '').trim()
    };
  }
  const start = toISODate(row['TestPress Course Start Date']);
  const ids = String(row['TestPress Course Ids'] || '').split('|').map(c => c.trim()).filter(Boolean);
  for (const cid of ids) {
    if (!enrolled[cid]) enrolled[cid] = new Map();
    const map = enrolled[cid];
    if (!map.has(email)) map.set(email, start);
    else {
      const prev = map.get(email);
      if (prev && (!start || start < prev)) map.set(email, start);
    }
  }
}

// ---- Per-lecture counts for the target date ----
const rawSessions = $('FORMATTING NODE: Compares the google sheet data with JSON Data').all()
  .map(i => i.json)
  .filter(d => d.session_date === targetDate);

// ---- Skip VPAR chapters (same rule as the reminder logic) ----
// EDIT: paste the same JWT line used in "Absentee Calculation Logic"
const jwt = "JWT eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJ1c2VyX2lkIjo4ODQ2MywidXNlcm5hbWUiOjg4NDYzLCJleHAiOjE3NzYzMTc4NDYsImVtYWlsIjoidXRwYWwyMzVAeWFob28uY29tIiwiaWQiOjg4NDYzLCJpbnN0aXR1dGUiOjE1MDl9.xcrfRS1jZA3H44ixYV0t_5HWgna7T0e5-lJG61ZtM8M";
const VPAR_TITLE_RE = /starter\s*module\s*vpar|vpar/i;
const chapterTitleById = {};
for (const course_id of [...new Set(rawSessions.map(d => String(d.course_id)))]) {
  let url = `https://catking.testpress.in/api/v2.5/admin/courses/${course_id}/chapters/?limit=100`;
  while (url) {
    const r = await helpers.request({
      method: 'GET', url,
      headers: { 'Authorization': jwt, 'Content-Type': 'application/json' },
      json: true
    });
    for (const c of (r.results || [])) chapterTitleById[String(c.id)] = String(c.name || c.title || '');
    url = r.next || null;
  }
}
const isVpar = id => VPAR_TITLE_RE.test(chapterTitleById[String(id)] || '');

// ---- Merge duplicates: same lecture title in the same batch counts once ----
const normTitle = t => String(t || '').toLowerCase().replace(/\s+/g, '');
const grouped = new Map();
for (const d of rawSessions) {
  if (isVpar(d.chapter_id)) continue;
  const cid = String(d.course_id);
  const key = `${cid}|${normTitle(d.lecture_title)}`;
  if (!grouped.has(key)) {
    grouped.set(key, { course_id: cid, lecture_title: d.lecture_title, session_date: d.session_date, attended: new Set() });
  }
  for (const e of (d.attended_emails || [])) grouped.get(key).attended.add(String(e).toLowerCase().trim());
}

const byBatch = {};
const rowsByBatch = {};
for (const s of grouped.values()) {
  const cid = s.course_id;
  const attended = s.attended;
  let absent = 0;
  const absentList = [];   // [name, email]
  const presentList = [];
  const nameOf = e => (studentInfo[e] && studentInfo[e].name) || '—';
  for (const [email, start] of (enrolled[cid] || new Map())) {
    if (start && s.session_date < start) continue;   // not started yet
    if (!attended.has(email)) { absent++; absentList.push([nameOf(email), email]); }
  }
  for (const email of attended) presentList.push([nameOf(email), email]);
  const sortList = arr => arr.sort((a, b) => (a[0] + a[1]).localeCompare(b[0] + b[1]));

  if (!rowsByBatch[cid]) rowsByBatch[cid] = [];
  rowsByBatch[cid].push(
    ['📘 ' + s.lecture_title, prettyDateOf(s.session_date)],
    ['Student Name', 'Email', 'Status'],
    ...sortList(presentList).map(([n, e]) => [n, e, 'Present']),
    ...sortList(absentList).map(([n, e]) => [n, e, 'Absent']),
    [`Present: ${presentList.length}  |  Absent: ${absentList.length}  |  Total: ${presentList.length + absentList.length}`],
    ['━━━━━━━━━━━━━━━━━━━━━━━━━━━━']   // separator (not blank, so rows stay contiguous for appending)
  );
  const present = attended.size;
  const total = present + absent;
  const pct = total ? (present / total) * 100 : 0;

  if (!byBatch[cid]) byBatch[cid] = [];
  byBatch[cid].push({ title: s.lecture_title, present, absent, pct });
}

// ---- Build the email ----
const prettyDate = new Date(targetDate + 'T00:00:00Z')
  .toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });

const th = 'style="border:1px solid #ccc;padding:6px 12px;background:#f2f2f2;text-align:left;"';
const td = 'style="border:1px solid #ccc;padding:6px 12px;"';

const batchIds = Object.keys(byBatch).sort((a, b) =>
  String(batchMap[a] || a).localeCompare(String(batchMap[b] || b), undefined, { numeric: true }));

let html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;">`;
html += `<h2 style="margin-bottom:4px;">Daily Attendance Summary</h2>`;
html += `<p style="margin-top:0;color:#555;">${esc(prettyDate)}</p>`;
html += `<p style="margin:12px 0 4px;">📋 <b>Student-wise attendance (all batches, one tab per batch):</b> <a href="${SHEET_URL}">Open Google Sheet</a></p>`;

if (batchIds.length === 0) {
  html += `<p>No live lectures with recorded attendance were found for this date.</p>`;
}

for (const cid of batchIds) {
  const label = batchMap[cid] || cid;
  html += `<h3 style="margin:24px 0 8px;border-bottom:2px solid #333;padding-bottom:4px;">Batch: ${esc(label)} <span style="color:#777;font-weight:normal;">(Course ${esc(cid)})</span></h3>`;
  for (const l of byBatch[cid].sort((a, b) => String(a.title).localeCompare(String(b.title)))) {
    html += `<p style="margin:12px 0 6px;"><b>Lecture:</b> ${esc(l.title)}</p>`;
    html += `<table style="border-collapse:collapse;margin-bottom:8px;">`;
    html += `<tr><th ${th}>Present</th><th ${th}>Absent</th><th ${th}>Attendance %</th></tr>`;
    html += `<tr><td ${td}>${l.present}</td><td ${td}>${l.absent}</td><td ${td}>${l.pct.toFixed(1)}%</td></tr>`;
    html += `</table>`;
  }
}
html += `</div>`;

const lectureCount = Object.values(byBatch).reduce((n, arr) => n + arr.length, 0);

return [{
  json: {
    subject: `Daily Attendance Summary – ${prettyDate}`,
    html,
    date: targetDate,
    batches: batchIds.length,
    lectures: lectureCount,
    sheet_url: SHEET_URL,
    // One item per batch in batchMap, so EVERY tab is cleared and rewritten each run
    sheet_batches: Object.keys(batchMap)
      .sort((a, b) => String(batchMap[a]).localeCompare(String(batchMap[b]), undefined, { numeric: true }))
      .map(cid => ({
        batch: String(batchMap[cid]),
        sheet_id: ATTENDANCE_SHEET_ID,
        header: [`Batch ${String(batchMap[cid])} — Attendance for ${prettyDate}`],
        rows: rowsByBatch[cid] || [[`No live lectures with recorded attendance on ${prettyDate}`]]
      }))
  }
}];
